    o+=person(j,g,s)
    if scarf: o+=f('M{0} {1}h{2}v{3}h-{2}z'.format(x-14*s,y-30*s,28*s,7*s))+ln('M{0} {1}v7M{2} {1}v7M{3} {1}v7'.format(x-6*s,y-30*s,x,x+6*s),1.2)
    return o
